inputs.code:
{
    // Timer setup
    duration: {
      displayName: 'Duration (ms)',
      group: 'Setup',
      type: 'number',
      default: 1000,
      set(value) {
        this._internal.duration = Math.max(0, value || 1000);
        this._internal.timeLeftOriginal = this._internal.duration / 1000;
        this._internal.timeLeft = this._internal.timeLeftOriginal;
      }
    },

    name: {
      displayName: 'Timer Name',
      group: 'Setup',
      type: 'string',
      default: 'unnamed',
      set(value) {
        this._internal.name = value || 'unnamed';
      }
    },

    isUi: {
      displayName: 'Is UI Timer',
      group: 'Setup',
      type: 'boolean',
      default: false,
      set(value) {
        this._internal.isUi = !!value;
      }
    },

    roomNodeId: {
      displayName: 'Room Node ID',
      group: 'Setup',
      type: 'string',
      set(id) {
        if (id) {
          const roomNode = xgenia.getNode(id);
          this._internal.roomUid = roomNode?.roomId || null;
        } else {
          this._internal.roomUid = null;
        }
      }
    },

    // Timer control
    start: {
      displayName: 'Start',
      group: 'Control',
      type: 'boolean',
      valueChangedToTrue() {
        this.startTimer();
      }
    },

    restart: {
      displayName: 'Restart',
      group: 'Control',
      type: 'boolean',
      valueChangedToTrue() {
        this.restartTimer();
      }
    },

    stop: {
      displayName: 'Stop',
      group: 'Control',
      type: 'boolean',
      valueChangedToTrue() {
        this.stopTimer();
      }
    },

    resolve: {
      displayName: 'Resolve',
      group: 'Control',
      type: 'boolean',
      valueChangedToTrue() {
        this.resolveTimer();
      }
    },

    reject: {
      displayName: 'Reject',
      group: 'Control',
      type: 'boolean',
      valueChangedToTrue() {
        this.rejectTimer();
      }
    }
  }

outputs.code:
{
    // Timer state
    isRunning: {
      displayName: 'Is Running',
      group: 'State',
      type: 'boolean',
      getter() {
        return !this._internal.done && !this._internal.rejected && this._internal.timeLeft > 0;
      }
    },

    timePassed: {
      displayName: 'Time Passed (s)',
      group: 'State',
      type: 'number',
      getter() {
        return this._internal.time;
      }
    },

    timeLeft: {
      displayName: 'Time Left (s)',
      group: 'State',
      type: 'number',
      getter() {
        return this._internal.timeLeft;
      }
    },

    progress: {
      displayName: 'Progress (0-1)',
      group: 'State',
      type: 'number',
      getter() {
        if (this._internal.timeLeftOriginal <= 0) return 0;
        return 1 - (this._internal.timeLeft / this._internal.timeLeftOriginal);
      }
    },

    // Timer events
    onStart: {
      displayName: 'Timer Started',
      group: 'Events',
      type: 'signal'
    },

    onFinish: {
      displayName: 'Timer Finished',
      group: 'Events',
      type: 'signal'
    },

    onReject: {
      displayName: 'Timer Rejected',
      group: 'Events',
      type: 'signal'
    },

    // Promise outputs
    promise: {
      displayName: 'Promise',
      group: 'Promise',
      type: 'object',
      getter() {
        return this._internal.promise;
      }
    }
  }
